"use client";

import { forwardRef } from "react";
import Engine from "./scale-slider-engine.jsx";
import css from "./scale-slider-styles";

export interface ScaleSliderHandle {
  next: () => void;
  prev: () => void;
  goTo: (index: number) => void;
}
export interface ScaleSliderProps {
  className?: string;
  images?: string[];
  direction?: "rtl" | "ltr";
  count?: "auto" | number;
  minScale?: number;
  autoplay?: number;
  drag?: number;
  scroll?: number;
  focusY?: number;
  radius?: number;
  parallax?: number;
}

export const ScaleSlider = forwardRef<ScaleSliderHandle, ScaleSliderProps>(
  function ScaleSlider(props, ref) {
    return (
      <>
        <style>{css}</style>
        <Engine {...props} ref={ref} />
      </>
    );
  },
);

import type { ScaleSliderProps, ScaleSliderHandle } from "./scale-slider";
import type { ForwardRefExoticComponent, RefAttributes } from "react";
declare const Engine: ForwardRefExoticComponent<
  ScaleSliderProps & RefAttributes<ScaleSliderHandle>
>;
export default Engine;
